CREATE TABLE IF NOT EXISTS `notification_sources` (`packageName` TEXT NOT NULL, `state` TEXT NOT NULL, `selectedAtEpochMs` INTEGER NOT NULL, `lastEventAtEpochMs` INTEGER, PRIMARY KEY(`packageName`));
CREATE TABLE IF NOT EXISTS `notification_scopes` (`packageName` TEXT NOT NULL, `conversationHash` TEXT NOT NULL, `approvedAtEpochMs` INTEGER NOT NULL, `encryptedLabel` TEXT NOT NULL, PRIMARY KEY(`packageName`, `conversationHash`));
CREATE TABLE IF NOT EXISTS `notification_health` (`singletonId` INTEGER NOT NULL, `state` TEXT NOT NULL, `lastConnectedAtEpochMs` INTEGER, `lastDisconnectedAtEpochMs` INTEGER, `gapCount` INTEGER NOT NULL, `lastGapStartAtEpochMs` INTEGER, `lastGapEndAtEpochMs` INTEGER, PRIMARY KEY(`singletonId`));
CREATE TABLE IF NOT EXISTS `notification_snapshots` (`snapshotId` TEXT NOT NULL, `packageName` TEXT NOT NULL, `keyHash` TEXT NOT NULL, `conversationHash` TEXT, `contentFingerprint` TEXT NOT NULL, `updateIndex` INTEGER NOT NULL, `encryptedPayload` TEXT, `observedAtEpochMs` INTEGER NOT NULL, `expiresAtEpochMs` INTEGER, `state` TEXT NOT NULL, `fromActiveAtReconnect` INTEGER NOT NULL, PRIMARY KEY(`snapshotId`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_notification_snapshots_packageName_keyHash_updateIndex` ON `notification_snapshots` (`packageName`, `keyHash`, `updateIndex`);
CREATE INDEX IF NOT EXISTS `index_notification_snapshots_packageName_conversationHash_state` ON `notification_snapshots` (`packageName`, `conversationHash`, `state`);
CREATE INDEX IF NOT EXISTS `index_notification_snapshots_expiresAtEpochMs` ON `notification_snapshots` (`expiresAtEpochMs`);
